import{_ as s,o as l,a as c,b as i}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"asc_sync_block_wait","link":"/api/SIMD-API/c_api/sync/asc_sync_block_wait"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/asc_sync_block_wait.md","filePath":"api/SIMD-API/c_api/sync/asc_sync_block_wait.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788435672000}'),e={name:"api/SIMD-API/c_api/sync/asc_sync_block_wait.md"};function n(t,a,d,p,o,_){return l(),c("div",null,[...a[0]||(a[0]=[i(`<div><article class="markdown-body"><h1>asc_sync_block_wait</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/sync/sync.h&quot;</code>。</p><p>本接口与<a href="asc_sync_block_arrive.html">asc_sync_block_arrive</a>配对使用，实现单AI Core内AIC与全部AIV之间的同步（<a href="system_sync_overview.html#fig_sync_control_mode">四种核间同步模式</a>中的模式2），核间同步实现的原理如下：</p><ul><li>全部AIV等待单个AIC的场景： <ul><li>单AI Core内AIC执行<code>asc_sync_block_arrive</code>后向调度模块发送通知，接着调度模块将该AI Core内M个AIV各自对应<code>flag_id</code>的计数器增加1。</li><li>各AIV上配对的<code>asc_sync_block_wait</code>检测到对应<code>flag_id</code>的计数器非0后解除阻塞并将计数器减1。</li></ul></li><li>单个AIC等待全部AIV的场景： <ul><li>单AI Core内M个AIV都执行<code>asc_sync_block_arrive</code>后向调度模块发送通知，接着调度模块将AIC对应<code>flag_id</code>的计数器增加1。</li><li>AIC上配对的<code>asc_sync_block_wait</code>检测到对应<code>flag_id</code>的计数器非0后解除阻塞并将计数器减1。</li></ul></li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_sync_block_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span>
<span class="w">                                           </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">flag_id</span><span class="p">)</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_sync_block_wait</span><span class="p">(</span><span class="n">pipe_t</span><span class="w"> </span><span class="n">pipe</span><span class="p">,</span>
<span class="w">                                           </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">flag_id</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">pipe</td><td align="left">输入</td><td align="left">标识阻塞哪条流水上后续指令，直到对应<code>flag_id</code>的计数器非0。</td></tr><tr><td align="left">flag_id</td><td align="left">输入</td><td align="left">核间同步的标记，用于标识同一组同步信号。取值范围为[0, 15]，每个<code>flag_id</code>各自拥有独立的4位计数器。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p><code>PIPE_S</code></p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>不同产品对参数<code>pipe</code>的生效情况如下： <div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，硬件支持配置核间同步模式和流水类型，输入参数<code>pipe</code><strong>生效</strong>，此时<code>asc_sync_block_wait</code>会阻塞<strong>指定流水</strong>的后续指令。</li></ul></div><div data-filter="A3,910b"><ul><li>针对如下产品，硬件不支持配置核间同步模式和流水类型，输入参数<code>pipe</code><strong>不生效</strong>，此时<code>asc_sync_block_wait</code>会阻塞<strong>全部流水</strong>的后续指令。 <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div></li></ul></div></li><li>用户需要确保配套使用（<code>flag_id</code>必须完全一致）<code>asc_sync_block_arrive</code>和<code>asc_sync_block_wait</code>，否则会出现未定义行为。</li><li>每个计数器最多连续累加15次（此时计数器的值为15），必须保证计数器的值不超过15，否则触发异常。</li><li><code>flag_id</code>取值范围为[0, 15]，超出范围值会被按位宽截断处理为低4位（例如，flagId=16时，截取后为0；flagId=17时，截取后为1）。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p><code>asc_sync_block_wait</code>需与<code>asc_sync_block_arrive</code>配对使用，具体调用示例请参考<a href="asc_sync_block_arrive.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">asc_sync_block_arrive调用示例</a>。</p></article></div>`,1)])])}const A=s(e,[["render",n]]);export{h as __pageData,A as default};
